#import "MenuMetersPref+Alerts.h"
#import "MenuMeterAlertsPrefsViewController.h"

@implementation MenuMetersPref (Alerts)

- (void)setupAlertsTab {
    // Must run before the toolbar is built: the toolbar's items are generated by
    // walking prefTabs.tabViewItems.
    if ([prefTabs indexOfTabViewItemWithIdentifier:@"bell"] != NSNotFound) return;

    MenuMeterAlertsPrefsViewController *controller =
        [[MenuMeterAlertsPrefsViewController alloc] init];

    // The identifier doubles as the toolbar icon: -toolbar:itemForItemIdentifier:
    // feeds it to +[NSImage imageWithSystemSymbolName:]. So it has to be a real
    // SF Symbol name, like the existing "cpu", "network" and "paperplane" tabs.
    NSTabViewItem *item = [[NSTabViewItem alloc] initWithIdentifier:@"bell"];
    item.label = NSLocalizedString(@"Notifs", @"alerts tab title");
    // Setting the view controller also installs its view and keeps it alive, so
    // there is nothing else holding on to the controller.
    item.viewController = controller;

    // Appended, never inserted: openAbout: selects the About tab by its index.
    [prefTabs addTabViewItem:item];
}

@end
